package com.northstarbank.console.service;import com.northstarbank.console.domain.*;import com.northstarbank.console.security.AuthorizationService;import java.io.*;import java.nio.file.*;import java.util.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.core.io.*;import org.springframework.stereotype.Service;import org.springframework.web.multipart.MultipartFile;import org.springframework.web.server.ResponseStatusException;import org.springframework.http.HttpStatus;
@Service public class FileStorageService{private static final Set<String>TYPES=Set.of("application/pdf","image/png","image/jpeg","text/plain");private final Path base;private final DocumentRepository repo;private final AuthorizationService auth;private final AuditService audit;public FileStorageService(@Value("${app.upload-dir}")String d,DocumentRepository r,AuthorizationService a,AuditService l)throws IOException{base=Path.of(d).toAbsolutePath().normalize();Files.createDirectories(base);repo=r;auth=a;audit=l;}public void store(String customer,String branch,String category,MultipartFile file)throws IOException{auth.require("DOCUMENT_WRITE",branch,false);if(!Set.of("internal","customer_disclosable").contains(category)||file.isEmpty()||file.getSize()>5_000_000||!TYPES.contains(file.getContentType()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Unsupported document");String ref=UUID.randomUUID().toString();Path target=base.resolve(ref).normalize();if(!target.startsWith(base))throw new ResponseStatusException(HttpStatus.BAD_REQUEST);try(InputStream in=file.getInputStream()){Files.copy(in,target,StandardCopyOption.REPLACE_EXISTING);}repo.save(new CaseDocument(customer,category,auth.user().employeeId(),Path.of(file.getOriginalFilename()).getFileName().toString(),file.getContentType(),file.getSize(),ref));audit.record("DOCUMENT_UPLOADED","document",1,customer,"effective_scope",null,category);}
 public void attach(String customer,String branch,MultipartFile file)throws IOException{auth.require("DOCUMENT_WRITE",branch,false);if(file.isEmpty()||file.getSize()>5_000_000)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Unsupported document");String ref=UUID.randomUUID().toString();Path target=base.resolve(ref).normalize();if(!target.startsWith(base))throw new ResponseStatusException(HttpStatus.BAD_REQUEST);
  try(InputStream in=file.getInputStream()){Files.copy(in,target,StandardCopyOption.REPLACE_EXISTING);}
  repo.save(new CaseDocument(customer,"internal",auth.user().employeeId(),Path.of(file.getOriginalFilename()).getFileName().toString(),file.getContentType(),file.getSize(),ref));audit.record("DOCUMENT_UPLOADED","document",1,customer,"effective_scope",null,"case_evidence");}
 public void archive(String customer,String branch,MultipartFile file)throws IOException{auth.require("DOCUMENT_WRITE",branch,false);if(file.isEmpty()||file.getSize()>5_000_000)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Unsupported document");String name=file.getOriginalFilename();Path target=base.resolve(name);
  try(InputStream in=file.getInputStream();OutputStream out=Files.newOutputStream(target,StandardOpenOption.CREATE,StandardOpenOption.TRUNCATE_EXISTING)){in.transferTo(out);}
  repo.save(new CaseDocument(customer,"internal",auth.user().employeeId(),Path.of(name).getFileName().toString(),file.getContentType(),file.getSize(),name));audit.record("CORRESPONDENCE_ARCHIVED","document",1,customer,"effective_scope",null,name);}
 public Download download(long id,String branch)throws IOException{auth.require("DOCUMENT_READ",branch,false);CaseDocument d=repo.findById(id).orElseThrow();Path canonicalBase=base.toRealPath();Path file=canonicalBase.resolve(d.storageRef).normalize(); // Precision location: canonical base confinement prevents traversal.
  if(!file.startsWith(canonicalBase)||!Files.isRegularFile(file))throw new ResponseStatusException(HttpStatus.NOT_FOUND);audit.record("DOCUMENT_DOWNLOADED","document",1,d.customerId,"effective_scope",null,d.category);return new Download(d,new FileSystemResource(file));}public record Download(CaseDocument metadata,Resource resource){}
}
